    fn pair(
        &self,
        a: &Sample,
        b: &Sample,
        arc: f64,
        medial: [f64; 2],
    ) -> Result<(Vec<f64>, f64, [f64; 2]), ()> {
        rows::pair_residual(&self.points, a, b, arc, medial, |a, dir, b| {
            self.projected(a, dir, b)
        })
    }
