struct Point {
    x: f64,
    y: f64,
}
impl Point {
    fn new(x: f32, y: f32) -> Self {
        Self {
            x: f64::from(x),
            y: -f64::from(y),
        }
    }
    fn along(self, vertical: bool) -> f64 {
        if vertical {
            self.y
        } else {
            self.x
        }
    }
    fn scan(self, vertical: bool) -> f64 {
        if vertical {
            self.x
        } else {
            self.y
        }
    }
}
#[derive(Clone)]
struct Segment {
    p: [Point; 4],
    degree: usize,
    next: usize,
}
impl Segment {
    fn at(&self, t: f64) -> Point {
        let mut p = self.p;
        for n in (1..=self.degree).rev() {
            for i in 0..n {
                p[i].x = p[i].x * (1.0 - t) + p[i + 1].x * t;
                p[i].y = p[i].y * (1.0 - t) + p[i + 1].y * t;
            }
        }
        p[0]
    }
    fn cuts(&self, vertical: bool) -> Vec<f64> {
        let mut cuts = vec![0.0, 1.0];
        let p = self.p.map(|p| p.scan(vertical));
        let d0 = p[1] - p[0];
        match self.degree {
            2 => {
                let d1 = p[2] - p[1];
                if d0 != d1 {
                    cuts.push(d0 / (d0 - d1));
                }
            }
            3 => {
                let d1 = p[2] - p[1];
                let d2 = p[3] - p[2];
                let a = d0 - 2.0 * d1 + d2;
                let b = 2.0 * (d1 - d0);
                let c = d0;
                if a == 0.0 {
                    if b != 0.0 {
                        cuts.push(-c / b);
                    }
                } else {
                    let disc = b * b - 4.0 * a * c;
                    if disc >= 0.0 {
                        let q = -0.5 * (b + disc.sqrt().copysign(b));
                        if q == 0.0 {
                            cuts.push(-b / (2.0 * a));
                        } else {
                            cuts.push(q / a);
                            cuts.push(c / q);
                        }
                    }
                }
            }
            _ => {}
